import [printf] from "std/c.bpl";

frame printBinary(n: int, bits: int) {
    loop (local i: int = bits - 1; i >= 0; i = i - 1) {
        if (((n >> i) & 1) == 1) {
            printf("1");
        } else {
            printf("0");
        }
    }
}

frame main() ret int {
    local a: int = 12;  # Binary: 1100
    local b: int = 10;  # Binary: 1010

    printf("a = %d = ", a); printBinary(a, 4); printf("\n");
    printf("b = %d = ", b); printBinary(b, 4); printf("\n");
    printf("\n");

    # AND: both bits must be 1
    local andResult: int = a & b;  # 1000 = 8
    printf("a & b = %d = ", andResult); printBinary(andResult, 4); printf("\n");

    # OR: either bit is 1
    local orResult: int = a | b;  # 1110 = 14
    printf("a | b = %d = ", orResult); printBinary(orResult, 4); printf("\n");

    # XOR: bits differ
    local xorResult: int = a ^ b;  # 0110 = 6
    printf("a ^ b = %d = ", xorResult); printBinary(xorResult, 4); printf("\n");

    # NOT: flip all bits (32-bit result shown truncated)
    local notResult: int = ~a;
    printf("~a = %d\n", notResult);

    return 0;
}

import [printf] from "std/c.bpl";

frame printBinary(n: int, bits: int) {
    loop (local i: int = bits - 1; i >= 0; i = i - 1) {
        if (((n >> i) & 1) == 1) {
            printf("1");
        } else {
            printf("0");
        }
    }
}

frame main() ret int {
    local n: int = 5;  # Binary: 0101

    printf("n = %d = ", n); printBinary(n, 8); printf("\n");
    printf("\n");

    # Left shift: multiply by 2^positions
    printf("n << 1 = %d = ", n << 1); printBinary(n << 1, 8); printf(" (×2)\n");
    printf("n << 2 = %d = ", n << 2); printBinary(n << 2, 8); printf(" (×4)\n");
    printf("n << 3 = %d = ", n << 3); printBinary(n << 3, 8); printf(" (×8)\n");

    printf("\n");

    local m: int = 40;  # Binary: 00101000
    printf("m = %d = ", m); printBinary(m, 8); printf("\n");

    # Right shift: divide by 2^positions
    printf("m >> 1 = %d = ", m >> 1); printBinary(m >> 1, 8); printf(" (÷2)\n");
    printf("m >> 2 = %d = ", m >> 2); printBinary(m >> 2, 8); printf(" (÷4)\n");
    printf("m >> 3 = %d = ", m >> 3); printBinary(m >> 3, 8); printf(" (÷8)\n");

    return 0;
}

import [printf] from "std/c.bpl";

# Permission flags (each is a power of 2)
local const READ: int    = 1;   # 0001
local const WRITE: int   = 2;   # 0010
local const EXECUTE: int = 4;   # 0100
local const DELETE: int  = 8;   # 1000

frame hasPermission(perms: int, flag: int) ret bool {
    return (perms & flag) != 0;
}

frame addPermission(perms: int, flag: int) ret int {
    return perms | flag;
}

frame removePermission(perms: int, flag: int) ret int {
    return perms & (~flag);
}

frame printPermissions(perms: int) {
    printf("Permissions: ");
    if (hasPermission(perms, READ))    { printf("READ "); }
    if (hasPermission(perms, WRITE))   { printf("WRITE "); }
    if (hasPermission(perms, EXECUTE)) { printf("EXECUTE "); }
    if (hasPermission(perms, DELETE))  { printf("DELETE "); }
    printf("\n");
}

frame main() ret int {
    # Start with no permissions
    local perms: int = 0;
    printf("Initial: ");
    printPermissions(perms);

    # Add read and write
    perms = addPermission(perms, READ);
    perms = addPermission(perms, WRITE);
    printf("After adding READ, WRITE: ");
    printPermissions(perms);

    # Add execute
    perms = addPermission(perms, EXECUTE);
    printf("After adding EXECUTE: ");
    printPermissions(perms);

    # Remove write
    perms = removePermission(perms, WRITE);
    printf("After removing WRITE: ");
    printPermissions(perms);

    # Check specific permission
    printf("\nHas READ? %d\n", hasPermission(perms, READ));
    printf("Has WRITE? %d\n", hasPermission(perms, WRITE));

    return 0;
}

import [printf] from "std/c.bpl";

# Extract bits from a color value (0xRRGGBB format)
frame getRed(color: int) ret int {
    return (color >> 16) & 0xFF;
}

frame getGreen(color: int) ret int {
    return (color >> 8) & 0xFF;
}

frame getBlue(color: int) ret int {
    return color & 0xFF;
}

frame makeColor(r: int, g: int, b: int) ret int {
    return (r << 16) | (g << 8) | b;
}

frame main() ret int {
    # Color in hex: 0xRRGGBB
    local skyBlue: int = 0x87CEEB;  # RGB(135, 206, 235)

    printf("Sky Blue (0x%X):\n", skyBlue);
    printf("  Red:   %d\n", getRed(skyBlue));
    printf("  Green: %d\n", getGreen(skyBlue));
    printf("  Blue:  %d\n", getBlue(skyBlue));

    # Create a custom color
    local custom: int = makeColor(255, 128, 64);
    printf("\nCustom (R=255, G=128, B=64):\n");
    printf("  Hex: 0x%X\n", custom);
    printf("  Red:   %d\n", getRed(custom));
    printf("  Green: %d\n", getGreen(custom));
    printf("  Blue:  %d\n", getBlue(custom));

    return 0;
}

