import [printf] from "std/c.bpl";

frame countSetBits(n: int) ret int {
    local count: int = 0;
    loop (n != 0) {
        if ((n & 1) == 1) {
            count = count + 1;
        }
        n = n >> 1;
    }
    return count;
}

frame main() ret int {
    printf("countSetBits(0) = %d\n", countSetBits(0));
    printf("countSetBits(1) = %d\n", countSetBits(1));
    printf("countSetBits(7) = %d (binary 111)\n", countSetBits(7));
    printf("countSetBits(13) = %d (binary 1101)\n", countSetBits(13));
    printf("countSetBits(15) = %d (binary 1111)\n", countSetBits(15));
    printf("countSetBits(255) = %d (binary 11111111)\n", countSetBits(255));

    return 0;
}
